<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8"><meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>EasyBiz ERP - Monthly Store Summary</title>
    <link rel="preconnect" href="https://fonts.googleapis.com"><link rel="preconnect" href="https://fonts.googleapis.com" crossorigin>
    <link href="https://fonts.googleapis.com/css2?family=Plus+Jakarta+Sans:wght@400;600;700;800&display=swap" rel="stylesheet">
    <style>
        :root { color-scheme: light; }
        * { box-sizing: border-box; }
        body { margin: 0; background: #eef2f8; color: #182033; font-family: 'Plus Jakarta Sans', Arial, sans-serif; }
        .toolbar { display: flex; align-items: center; justify-content: space-between; gap: 1rem; max-width: 1020px; margin: 0 auto; padding: 1.25rem 1rem; }
        .toolbar a, .toolbar button { border: 0; border-radius: 10px; padding: .75rem 1rem; font: inherit; font-weight: 700; cursor: pointer; text-decoration: none; }
        .back { color: #4c5a72; background: transparent; } .print { color: #fff; background: #004ac6; } .pdf { color: #004ac6; background: #dbe7ff; }
        .toolbar-title { flex: 1; } .toolbar-title strong { display: block; font-size: 1.05rem; } .toolbar-title span { color: #6d7890; font-size: .8rem; }
        .paper { width: 210mm; min-height: 297mm; margin: 0 auto 2rem; padding: 16mm 18mm; background: #fff; box-shadow: 0 8px 35px rgba(28, 42, 67, .13); }
        .brand { display: flex; justify-content: space-between; gap: 2rem; border-bottom: 3px solid #004ac6; padding-bottom: 1rem; }
        .brand-mark { display: inline-flex; align-items: center; gap: .6rem; color: #004ac6; font-size: 1.4rem; font-weight: 800; } .mark { display: grid; place-items: center; width: 34px; height: 34px; border-radius: 9px; color: #fff; background: #004ac6; font-size: 1.1rem; }
        .eyebrow { margin: 0 0 .25rem; color: #69758b; font-size: .68rem; font-weight: 800; letter-spacing: .08em; text-transform: uppercase; } h1 { margin: 0; font-size: 1.35rem; } h2 { margin: 0; font-size: .9rem; } p { margin: .3rem 0; font-size: .73rem; line-height: 1.5; } .muted { color: #66738a; }
        .doc-meta { text-align: right; } .doc-meta strong { color: #004ac6; font-size: .9rem; }
        .section { margin-top: 1.25rem; } .section-title { display: flex; align-items: center; gap: .45rem; margin-bottom: .6rem; color: #004ac6; font-size: .78rem; font-weight: 800; text-transform: uppercase; letter-spacing: .05em; }
        .section-title::before { content: ''; width: 4px; height: 16px; border-radius: 3px; background: #004ac6; }
        .metrics { display: grid; grid-template-columns: repeat(3, 1fr); gap: .6rem; } .metric { padding: .75rem; border: 1px solid #dfe5ef; border-radius: 9px; } .metric .label { color: #637087; font-size: .65rem; font-weight: 700; } .metric .value { margin: .3rem 0; font-size: 1.15rem; font-weight: 800; } .metric .note { color: #637087; font-size: .62rem; }
        table { width: 100%; border-collapse: collapse; } th, td { padding: .48rem .4rem; border-bottom: 1px solid #e5e9f0; text-align: left; font-size: .68rem; vertical-align: top; } th { color: #637087; background: #f4f7fb; font-size: .62rem; text-transform: uppercase; } td.amount, th.amount { text-align: right; white-space: nowrap; } .positive { color: #006c4a; font-weight: 800; } .negative { color: #ba1a1a; }
        .two-col { display: grid; grid-template-columns: 1.3fr .7fr; gap: 1rem; } .rank-list, .week-list { display: grid; gap: .42rem; } .rank, .week { display: flex; align-items: center; justify-content: space-between; gap: .75rem; padding: .45rem .55rem; border-radius: 7px; background: #f6f8fc; } .rank-name { font-size: .67rem; font-weight: 700; } .rank-detail { color: #6b778b; font-size: .61rem; } .rank-value { color: #004ac6; font-size: .68rem; font-weight: 800; white-space: nowrap; }
        .recommendation { margin-top: .65rem; padding: .6rem .75rem; border-left: 3px solid #006c4a; border-radius: 5px; background: #e9f8f1; color: #285b48; font-size: .67rem; }
        .signatures { display: grid; grid-template-columns: 1fr 1fr; gap: 2rem; margin-top: 1.5rem; } .signature { padding-top: 1.3rem; border-top: 1px solid #aab4c4; } .signature strong { display: block; font-size: .7rem; } .signature span { color: #657188; font-size: .62rem; }
        .footer { margin-top: 1.25rem; padding-top: .7rem; border-top: 1px solid #dce2eb; text-align: center; color: #748095; font-size: .6rem; }
        @media (max-width: 850px) { .paper { width: calc(100% - 1rem); min-height: auto; padding: 1.25rem; } .brand { flex-direction: column; } .doc-meta { text-align: left; } .toolbar { flex-wrap: wrap; } .toolbar-title { order: -1; flex-basis: 100%; } }
        @page { size: A4 portrait; margin: 0; }
        @media print { body { width: 210mm; min-height: 297mm; background: #fff; } .toolbar { display: none; } .paper { width: 210mm; min-height: 297mm; margin: 0; box-shadow: none; page-break-after: always; } }
    </style>
</head>
