    <div class="toolbar"><a href="{{ route('reports') }}" class="back">← Back to Reports</a><div class="toolbar-title"><strong>Print Preview: Store Summary Report</strong><span>A4 (210mm × 297mm) · September 2026</span></div><button type="button" class="pdf" onclick="window.print()">↓ Save as PDF</button><button type="button" class="print" onclick="window.print()">Print Document</button></div>
